package com.yeyamo_mobile.api.commerce_service.persistence;
import com.fasterxml.jackson.annotation.JsonIgnore;import jakarta.persistence.*;import java.math.*;import java.time.*;import java.util.*;import static com.yeyamo_mobile.api.commerce_service.domain.CommerceTypes.*;
@Entity @Table(name="commerce_orders") public class CommerceOrder{
 @Id public UUID id;public String reference;@Column(name="idempotency_key")public String idempotencyKey;@Column(name="user_id")public String userId;@Column(name="partner_id")public String partnerId;@Column(name="source_entity_id")public String sourceEntityId;@Enumerated(EnumType.STRING)@Column(name="product_type")public ProductType productType;@Enumerated(EnumType.STRING)public OrderStatus status;
 public BigDecimal subtotal;@Column(name="discount_amount")public BigDecimal discountAmount;@Column(name="tax_amount")public BigDecimal taxAmount;@Column(name="service_fee")public BigDecimal serviceFee;@Column(name="commission_amount")public BigDecimal commissionAmount;@Column(name="total_amount")public BigDecimal totalAmount;@Column(name="partner_net_amount")public BigDecimal partnerNetAmount;public String currency;@Column(name="promotion_id")public UUID promotionId;@Column(name="pricing_rule_version")public int pricingRuleVersion;@Column(name="commission_rule_version")public Integer commissionRuleVersion;@Column(name="payment_id")public String paymentId;@JsonIgnore @Column(name="payment_operator",length=20)public String paymentOperator;@JsonIgnore @Column(name="payment_country_code",length=2)public String paymentCountryCode;@JsonIgnore @Column(name="payment_phone_number",length=16)public String paymentPhoneNumber;@Column(name="created_at")public Instant createdAt;@Column(name="updated_at")public Instant updatedAt;@Column(name="paid_at")public Instant paidAt;
 @PrePersist void create(){createdAt=updatedAt=Instant.now();}@PreUpdate void update(){updatedAt=Instant.now();}
}
